from collections import Counter

def transform(grid):
    """Connect collinear occurrences of the sparse marker with color 3."""
    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    marker = next(x for x in Counter(x for row in grid for x in row) if x != background)
    out = [row[:] for row in grid]
    # Draw the gaps between the outermost markers in each row and column.
    # The marker cells themselves keep their original color.
    for r in range(h):
        cols = [c for c, x in enumerate(grid[r]) if x == marker]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 2:
            for r in range(min(rows) + 1, max(rows)):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out

